import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Search, 
  Filter, 
  Plus, 
  Eye, 
  Edit, 
  Download,
  Share2,
  Trash2,
  ChevronDown,
  X,
  CheckCircle,
  Clock,
  AlertCircle,
  FileText,
  BarChart3,
  TrendingUp,
  TrendingDown,
  Building2,
  Users,
  Target,
  Shield,
  Calendar,
  Mail,
  FileDown
} from 'lucide-react';

const Reports = () => {
  const [reports, setReports] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [reportTypeFilter, setReportTypeFilter] = useState('all');
  const [dateRange, setDateRange] = useState('30days');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Mock data for demonstration
  const mockReports = [
    {
      id: 'RPT-001',
      title: 'Tech Park Campus - Readiness Report',
      type: 'property-readiness',
      propertyName: 'Tech Park Campus',
      buildingName: 'All Buildings',
      date: '2024-01-20',
      status: 'ready',
      readinessScore: 92,
      generatedBy: 'Sarah Johnson',
      lastUpdated: '2024-01-20'
    },
    {
      id: 'RPT-002',
      title: 'Innovation Tower A - Survey Report',
      type: 'building-survey',
      propertyName: 'Tech Park Campus',
      buildingName: 'Innovation Tower A',
      date: '2024-01-19',
      status: 'ready',
      readinessScore: 88,
      generatedBy: 'Emily Rodriguez',
      lastUpdated: '2024-01-19'
    },
    {
      id: 'RPT-003',
      title: 'Emily Rodriguez - Performance Report',
      type: 'engineer-performance',
      propertyName: 'All Properties',
      buildingName: 'N/A',
      date: '2024-01-18',
      status: 'excellent',
      readinessScore: 94,
      generatedBy: 'Michael Chen',
      lastUpdated: '2024-01-18'
    },
    {
      id: 'RPT-004',
      title: 'Downtown Office Complex - Readiness Report',
      type: 'property-readiness',
      propertyName: 'Downtown Office Complex',
      buildingName: 'All Buildings',
      date: '2024-01-17',
      status: 'attention',
      readinessScore: 65,
      generatedBy: 'Sarah Johnson',
      lastUpdated: '2024-01-17'
    },
    {
      id: 'RPT-005',
      title: 'Data Center D - Critical Issues Report',
      type: 'building-survey',
      propertyName: 'Tech Park Campus',
      buildingName: 'Data Center D',
      date: '2024-01-16',
      status: 'blocked',
      readinessScore: 45,
      generatedBy: 'David Kim',
      lastUpdated: '2024-01-16'
    }
  ];

  useEffect(() => {
    setReports(mockReports);
  }, []);

  const getReportTypeBadge = (type) => {
    const typeConfig = {
      'property-readiness': {
        label: 'Property Readiness',
        color: 'bg-blue-100 text-blue-800 border-blue-200',
        icon: Building2
      },
      'building-survey': {
        label: 'Building Survey',
        color: 'bg-green-100 text-green-800 border-green-200',
        icon: Shield
      },
      'engineer-performance': {
        label: 'Engineer Performance',
        color: 'bg-purple-100 text-purple-800 border-purple-200',
        icon: Users
      }
    };

    const config = typeConfig[type] || typeConfig['property-readiness'];
    const Icon = config.icon;

    return (
      <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border ${config.color} text-sm font-medium`}>
        <Icon className="w-3.5 h-3.5" />
        {config.label}
      </div>
    );
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'ready': {
        color: 'bg-green-100 text-green-800 border-green-200',
        icon: CheckCircle,
        label: 'Ready'
      },
      'attention': {
        color: 'bg-yellow-100 text-yellow-800 border-yellow-200',
        icon: AlertCircle,
        label: 'Needs Attention'
      },
      'blocked': {
        color: 'bg-red-100 text-red-800 border-red-200',
        icon: AlertCircle,
        label: 'Blocked'
      },
      'excellent': {
        color: 'bg-emerald-100 text-emerald-800 border-emerald-200',
        icon: Target,
        label: 'Excellent'
      }
    };

    const config = statusConfig[status] || statusConfig['ready'];
    const Icon = config.icon;

    return (
      <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border ${config.color} text-sm font-medium`}>
        <Icon className="w-3.5 h-3.5" />
        {config.label}
      </div>
    );
  };

  const filteredReports = reports.filter(report => {
    const matchesSearch = report.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         report.propertyName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         report.id.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesType = reportTypeFilter === 'all' || report.type === reportTypeFilter;
    return matchesSearch && matchesType;
  });

  const handleViewReport = (report) => {
    // Navigate to report detail or open modal
    alert(`Viewing report: ${report.title}`);
  };

  const handleEditReport = (report) => {
    alert(`Editing report: ${report.title}`);
  };

  const handleDeleteReport = (reportId) => {
    if (window.confirm('Are you sure you want to delete this report?')) {
      setReports(prev => prev.filter(report => report.id !== reportId));
    }
  };

  const handleExportReport = (report, format) => {
    alert(`Exporting ${report.title} as ${format.toUpperCase()}`);
  };

  const handleShareReport = (report) => {
    alert(`Sharing report: ${report.title}`);
  };

  return (
    <div className="w-full">
      {/* Header */}
      <div className="bg-white shadow-sm border-b border-gray-200">
        <div className="px-6 lg:px-10 py-6">
          <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
            {/* Left side - Title and description */}
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Reports & Analytics</h1>
              <p className="text-gray-500 mt-1">Decision-ready insights for ISP deployment planning</p>
            </div>

            {/* Right side - Actions */}
            <div className="flex items-center gap-3">
              <div className="relative">
                <Search className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 transform -translate-y-1/2" />
                <input
                  type="text"
                  placeholder="Search reports..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent w-64"
                />
              </div>

              <select
                value={reportTypeFilter}
                onChange={(e) => setReportTypeFilter(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="all">All Reports</option>
                <option value="property-readiness">Property Readiness</option>
                <option value="building-survey">Building Survey</option>
                <option value="engineer-performance">Engineer Performance</option>
              </select>

              <select
                value={dateRange}
                onChange={(e) => setDateRange(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="7days">Last 7 Days</option>
                <option value="30days">Last 30 Days</option>
                <option value="90days">Last 90 Days</option>
                <option value="1year">Last Year</option>
              </select>

              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors font-medium flex items-center gap-2"
              >
                <Plus className="w-4 h-4" />
                New Report
              </motion.button>
            </div>
          </div>
        </div>
      </div>

      {/* Reports Table */}
      <div className="px-6 lg:px-10 py-8">
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <table className="w-full">
            <thead className="bg-gray-50 border-b border-gray-200">
              <tr>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Report ID
                </th>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Title
                </th>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Type
                </th>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Property
                </th>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Building
                </th>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Status
                </th>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Readiness
                </th>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Generated By
                </th>
                <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Last Updated
                </th>
                <th className="px-6 py-4 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {filteredReports.map((report, index) => (
                <motion.tr
                  key={report.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.05 }}
                  className="hover:bg-gray-50 transition-colors duration-150"
                >
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-gray-900">{report.id}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-sm font-medium text-gray-900">{report.title}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {getReportTypeBadge(report.type)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm text-gray-900">{report.propertyName}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm text-gray-900">{report.buildingName}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {getStatusBadge(report.status)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-2">
                      <div className="flex-1 bg-gray-200 rounded-full h-2 max-w-16">
                        <div 
                          className={`h-2 rounded-full ${
                            report.readinessScore >= 80 ? 'bg-green-500' :
                            report.readinessScore >= 60 ? 'bg-yellow-500' : 'bg-red-500'
                          }`}
                          style={{ width: `${report.readinessScore}%` }}
                        />
                      </div>
                      <span className="text-sm font-medium text-gray-900">{report.readinessScore}%</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm text-gray-900">{report.generatedBy}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm text-gray-500">{report.lastUpdated}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right">
                    <div className="flex items-center justify-end gap-2">
                      {/* View Report */}
                      <motion.button
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        onClick={() => handleViewReport(report)}
                        className="p-2 text-gray-600 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors duration-150"
                        title="View Report"
                      >
                        <Eye className="w-4 h-4" />
                      </motion.button>

                      {/* Edit */}
                      <motion.button
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        onClick={() => handleEditReport(report)}
                        className="p-2 text-gray-600 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors duration-150"
                        title="Edit Report"
                      >
                        <Edit className="w-4 h-4" />
                      </motion.button>

                      {/* Export */}
                      <div className="relative group">
                        <motion.button
                          whileHover={{ scale: 1.1 }}
                          whileTap={{ scale: 0.9 }}
                          className="p-2 text-gray-600 hover:text-green-600 hover:bg-green-50 rounded-lg transition-colors duration-150"
                          title="Export Report"
                        >
                          <Download className="w-4 h-4" />
                        </motion.button>
                        <div className="absolute right-0 top-full mt-1 w-32 bg-white border border-gray-200 rounded-lg shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-10">
                          <button
                            onClick={() => handleExportReport(report, 'pdf')}
                            className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition-colors"
                          >
                            Export PDF
                          </button>
                          <button
                            onClick={() => handleExportReport(report, 'csv')}
                            className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition-colors"
                          >
                            Export CSV
                          </button>
                        </div>
                      </div>

                      {/* Share */}
                      <motion.button
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        onClick={() => handleShareReport(report)}
                        className="p-2 text-gray-600 hover:text-purple-600 hover:bg-purple-50 rounded-lg transition-colors duration-150"
                        title="Share Report"
                      >
                        <Share2 className="w-4 h-4" />
                      </motion.button>

                      {/* Delete */}
                      <motion.button
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        onClick={() => handleDeleteReport(report.id)}
                        className="p-2 text-gray-600 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors duration-150"
                        title="Delete Report"
                      >
                        <Trash2 className="w-4 h-4" />
                      </motion.button>
                    </div>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Empty State */}
        {filteredReports.length === 0 && (
          <div className="text-center py-12">
            <FileText className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">No reports found</h3>
            <p className="text-gray-500 mb-6">Try adjusting your search or filter criteria</p>
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => {
                setSearchTerm('');
                setReportTypeFilter('all');
              }}
              className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors font-medium"
            >
              Clear Filters
            </motion.button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Reports;
